const $=id=>document.getElementById(id);
let catalog=[],world,country=null,regions=null,mode='learn',continent='all',queue=[],qIndex=0,correct=0,wrong=[],locked=false,timer=null,request=0,projection,path,layer,labelLayer,W,H,zoomK=1;
let completed=new Set(), skipped=[], revealed=null, wrongSelected=null, finished=false;
const svg=d3.select('#map'),scene=svg.append('g'),graticule=scene.append('path').attr('fill','none').attr('stroke','#dfe8d8').attr('stroke-width',.5),shapes=scene.append('g'),pins=scene.append('g'),labels=scene.append('g');
const zoom=d3.zoom().scaleExtent([1,18]).on('zoom',e=>{scene.attr('transform',e.transform);zoomK=e.transform.k;labels.selectAll('g').attr('transform',d=>`translate(${anchor(d)}) scale(${1/zoomK})`);pins.selectAll('circle').attr('r',d=>d.tiny?4/zoomK:3/zoomK);layoutLabels()});svg.call(zoom).on('dblclick.zoom',null);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nonLatin=s=>/[^\p{Script=Latin}\p{Number}\p{Punctuation}\p{Separator}\p{Mark}]/u.test(s);
function nameLines(p){const a=[p.fallback?(p.en?p.en+'（原文待補）':'原文待補'):(p.local||'原文待補')];if(p.script==='non-latin'||(!p.script&&nonLatin(p.local||'')))a.push(p.en||'英文待補');a.push(p.zh||'中文待補');return a}
function nameHTML(p){const lines=nameLines(p);return lines.map((n,i)=>`<span class="${i===0?'name-local':i===lines.length-1?'name-zh':'name-en'}">${esc(n)}</span>`).join('')+(p.fallback&&p.en?`<span class="name-note">暫用來源名稱：${esc(p.en)}</span>`:'')}
function cancel(){clearTimeout(timer);timer=null;svg.interrupt();locked=false;hideTip()}
function setLoading(v){$('loading').hidden=!v}
function showTip(e,html){$('tooltip').innerHTML=html;$('tooltip').hidden=false;const rect=$('map').getBoundingClientRect();$('tooltip').style.left=Math.max(8,Math.min(e.clientX-rect.left+13,W-245))+'px';$('tooltip').style.top=Math.min(e.clientY-rect.top+15,H-95)+'px'}
function hideTip(){$('tooltip').hidden=true}
function anchor(f){const c=f.properties.label_point?projection(f.properties.label_point):path.centroid(f);return Number.isFinite(c[0])?c:[W/2,H/2]}
function dims(){const b=$('map').getBoundingClientRect();W=b.width;H=b.height;svg.attr('viewBox',`0 0 ${W} ${H}`)}
function renderMap(){dims();labels.selectAll('*').remove();svg.call(zoom.transform,d3.zoomIdentity);if(!country){projection=d3.geoNaturalEarth1().fitExtent([[25,67],[W-25,H-55]],world)}else{const fc=regions?.features.length?regions:{type:'FeatureCollection',features:world.features.filter(f=>f.properties.id===country.id)};projection=d3.geoMercator().rotate([-country.lon,0]).fitExtent([[45,80],[W-45,H-65]],fc)}path=d3.geoPath(projection);graticule.attr('d',country?null:path(d3.geoGraticule10()));shapes.selectAll('*').remove();pins.selectAll('*').remove();labels.selectAll('*').remove();if(!country){
shapes.selectAll('path').data(world.features).join('path').attr('d',path).attr('class','country-path').attr('tabindex',-1).on('click',(e,f)=>selectCountry(f.properties.id)).on('mousemove',(e,f)=>{const c=catalog.find(c=>c.id===f.properties.id);showTip(e,`<strong>${esc(c.name)}</strong><br><small>${esc(c.en)} · ${c.count?c.count+' 個行政區':'細分資料待補'}</small>`)}).on('mouseleave',hideTip);
const small=world.features.filter(f=>path.area(f)<9).map(f=>{const c=catalog.find(c=>c.id===f.properties.id);return {id:c.id,c,point:projection([c.lon,c.lat])}});pins.selectAll('circle').data(small).join('circle').attr('cx',d=>d.point[0]).attr('cy',d=>d.point[1]).attr('r',3).attr('class','country-marker').on('click',(e,d)=>selectCountry(d.id)).on('mousemove',(e,d)=>showTip(e,esc(d.c.name))).on('mouseleave',hideTip);
}else{const fs=regions?.features||[];shapes.selectAll('path').data(fs).join('path').attr('d',path).attr('class','region-path').attr('data-id',d=>d.properties.id).on('click',(e,f)=>regionClick(f,e)).on('mousemove',(e,f)=>{if(mode==='learn'||completed.has(f.properties.id))showTip(e,nameHTML(f.properties))}).on('mouseleave',hideTip);pins.selectAll('circle').data(fs.filter(f=>path.area(f)<38).map(f=>Object.assign(f,{tiny:true}))).join('circle').attr('cx',d=>anchor(d)[0]).attr('cy',d=>anchor(d)[1]).attr('r',4).attr('class','tiny-region').on('click',(e,f)=>regionClick(f,e)).on('mousemove',(e,f)=>{if(mode==='learn'||completed.has(f.properties.id))showTip(e,nameHTML(f.properties))}).on('mouseleave',hideTip);refreshRegionState();}}
function drawLabels(fs){labels.selectAll('*').remove();const ordered=[...fs].sort((a,b)=>(b===revealed)-(a===revealed)||path.area(b)-path.area(a));const g=labels.selectAll('g').data(ordered).join('g');g.each(function(f){const lines=nameLines(f.properties);const t=d3.select(this).append('text').attr('class','region-label');lines.forEach((s,i)=>t.append('tspan').attr('x',0).attr('dy',i?13:-(lines.length-1)*6).attr('font-size',i?9:10).text(s));this._labelBox=t.node().getBBox()});layoutLabels()}
function countryList(){const term=$('search').value.trim().toLowerCase();let cs=catalog.filter(c=>(continent==='all'||continent==='other'?!['Asia','Europe'].includes(c.continent)||continent==='all':c.continent===continent)&&(!term||(c.name+' '+c.en+' '+c.id).toLowerCase().includes(term)));const popular=['TWN','JPN','VNM','USA','FRA','DEU','KOR','GBR','ITA','ESP'];cs.sort((a,b)=>{let aa=popular.indexOf(a.id),bb=popular.indexOf(b.id);return (aa<0?999:aa)-(bb<0?999:bb)||a.en.localeCompare(b.en)});$('listCount').textContent=cs.length+' 個';$('countryList').replaceChildren();if(!cs.length){$('countryList').textContent='找不到符合的國家，試試英文名稱。';return}for(const c of cs){const b=document.createElement('button');b.className='country-row';b.innerHTML=`<span class="country-icon">${esc(c.id)}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.en)}</small></span><span class="arrow">${c.count||'—'} ↗</span>`;b.onclick=()=>selectCountry(c.id);$('countryList').append(b)}}
async function selectCountry(id){if(!confirmLeave())return;cancel();clearRound();const token=++request;country=catalog.find(c=>c.id===id);regions=null;mode='learn';$('explorePanel').hidden=true;$('countryPanel').hidden=false;$('countryName').textContent=country.name;$('regionCount').textContent=country.count+' 個行政區';$('dataNote').textContent=country.note+' 來源：'+country.source+'；取得日期：'+country.retrieved_at+'。';$('dataMeta').textContent=`${country.learning_level} · ${country.boundary_version} · 收錄 ${country.count}${country.expected_count?' / '+country.expected_count:''} 區`;$('eyebrow').textContent='EXPLORE / '+country.en.toUpperCase();$('title').textContent=country.name+'，從地名到位置。';$('subtitle').textContent='學習地名與輪廓，再透過點選測驗加深記憶。';$('introStat').hidden=true;$('mapCaption').textContent=country.name;$('mapHint').textContent='滾輪縮放 · 拖曳移動';$('regionSearch').value='';$('quiz').disabled=true;$('regionList').replaceChildren();setLoading(true);setModeUI();try{const loaded=country.count?await getJSON('data/'+id+'.json'):{type:'FeatureCollection',features:[]};if(token!==request)return;validateRegions(loaded);regions=loaded;$('quiz').disabled=!regions.features.length;renderRegionList();renderMap();$('legend').textContent=country.count?'原文 / 英文（非拉丁文字）/ 中文 · 放大看清地名':'此地區尚無細分邊界資料';if(!country.count)$('regionList').textContent='來源尚無此地的一級行政區邊界，暫無法進行測驗。'}catch(e){if(token!==request)return;$('regionList').innerHTML='<p>地圖載入失敗。</p><button class=secondary id=retryData>重新載入</button>';$('retryData').onclick=()=>selectCountry(id);$('quiz').disabled=true;renderMap()}finally{if(token===request)setLoading(false)}}
function goHome(){if(!confirmLeave())return;cancel();clearRound();request++;country=null;regions=null;setLoading(false);$('explorePanel').hidden=false;$('countryPanel').hidden=true;$('eyebrow').textContent='你的下一站，從地圖開始';$('title').innerHTML='認識世界，<em>一區一區來。</em>';$('subtitle').textContent='選擇一個國家，探索地名，再挑戰你的地理直覺。';$('introStat').hidden=false;$('mapCaption').textContent='世界地圖';$('mapHint').textContent='點選國家，開始探索';$('legend').innerHTML='<i></i> 選擇一片土地，開啟一段旅程';renderMap()}
function setModeUI(){$('learn').classList.toggle('selected',mode==='learn');$('quiz').classList.toggle('selected',mode==='quiz');$('learnInfo').hidden=mode!=='learn';$('quizInfo').hidden=mode!=='quiz'}
function learn(){if(!confirmLeave())return;cancel();clearRound();mode='learn';setModeUI();renderMap();$('legend').textContent='地名隨縮放顯示 · 懸停或點選查看完整名稱'}
function renderRegionList(){const term=$('regionSearch').value.toLowerCase();$('regionList').replaceChildren();for(const f of regions.features.filter(f=>nameLines(f.properties).join(' ').toLowerCase().includes(term))){const b=document.createElement('button');b.className='region-row';b.innerHTML=nameHTML(f.properties);b.onclick=()=>focusRegion(f);$('regionList').append(b)}}
function focusRegion(f){const [[x0,y0],[x1,y1]]=path.bounds(f),k=Math.min(8,Math.max(1,.55/Math.max((x1-x0)/W,(y1-y0)/H)));svg.transition().duration(450).call(zoom.transform,d3.zoomIdentity.translate(W/2,H/2).scale(k).translate(-(x0+x1)/2,-(y0+y1)/2));shapes.selectAll('path').classed('active',d=>d===f)}
function regionClick(f,e){if(mode==='learn'||completed.has(f.properties.id)){if(mode==='learn')shapes.selectAll('path').classed('active',d=>d===f);if(e)showTip(e,nameHTML(f.properties));if(mode==='quiz'&&!locked)$('feedback').textContent='此區域已完成，請選擇尚未完成的區域。';return}answer(f)}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startQuiz(){if(!regions?.features.length||!confirmLeave())return;cancel();clearRound();mode='quiz';queue=shuffle([...regions.features]);setModeUI();$('skip').hidden=false;$('skip').textContent='不知道／顯示答案';$('skip').onclick=()=>answer(null);$('restart').textContent='重新開始';$('results').hidden=true;renderMap();nextQuestion()}
function nextQuestion(){locked=false;revealed=null;wrongSelected=null;hideTip();$('nextQuestion').hidden=true;$('skip').disabled=false;$('progressFill').style.width=(completed.size/queue.length*100)+'%';$('score').textContent='答對 '+correct+' 題';refreshRegionState();if(qIndex>=queue.length){finish();return}$('questionCount').textContent=`第 ${qIndex+1} / ${queue.length} 題`;$('questionName').innerHTML=nameHTML(queue[qIndex].properties);$('feedback').className='';$('feedback').textContent='點選你認為正確的區域。';$('legend').textContent='未完成區域隱藏地名 · 已完成區域保留'}
function markAnswer(target){revealed=target;refreshRegionState();ensureVisible(target)}
function answer(selected){if(locked||finished||qIndex>=queue.length)return;if(selected&&completed.has(selected.properties.id)){$('feedback').textContent='此區域已完成。';return}locked=true;const target=queue[qIndex],ok=selected===target;completed.add(target.properties.id);if(ok)correct++;else if(selected)wrong.push(target);else skipped.push(target);wrongSelected=selected&&!ok?selected:null;$('skip').disabled=true;markAnswer(target);$('feedback').className=ok?'good':'bad';$('feedback').textContent=ok?'✓ 答對了！1 秒後繼續。':`${selected?'✕ 答錯了':'已跳過'}。正確區域已標示，準備好後按「${qIndex===queue.length-1?'查看結果':'下一題'}」。`;$('score').textContent='答對 '+correct+' 題';$('progressFill').style.width=(completed.size/queue.length*100)+'%';$('legend').textContent=ok?'✓ 本題正解 · 已完成區域持續保留':'✓ 綠色：本題正解 · 橘色：錯選位置';if(ok)timer=setTimeout(advance,1000);else{$('nextQuestion').hidden=false;$('nextQuestion').textContent=qIndex===queue.length-1?'查看結果 →':'下一題 →'}}
function finish(){locked=true;finished=true;revealed=null;wrongSelected=null;refreshRegionState();$('questionCount').textContent='本輪完成';$('progressFill').style.width='100%';$('questionName').innerHTML=`<div class="result-score">${Math.round(correct/queue.length*100)}<small>%</small></div><span class="name-zh">答對 ${correct} / ${queue.length} 題</span>`;$('feedback').className='good';$('feedback').textContent=`共 ${queue.length} 題：答對 ${correct}、答錯 ${wrong.length}、跳過 ${skipped.length}。`;$('skip').hidden=true;$('nextQuestion').hidden=true;$('restart').textContent='再測一次';$('results').hidden=false;$('resultList').innerHTML=[...wrong.map(f=>({f,label:'答錯'})),...skipped.map(f=>({f,label:'跳過'}))].map(({f,label})=>`<div class="result-item"><small>${label}</small>${nameHTML(f.properties)}</div>`).join('')||'<p>全部答對，太棒了！</p>';$('legend').textContent='本輪完成 · 地名與區域保留 · 成績不儲存'}
async function getJSON(url){const r=await fetch(url);if(!r.ok)throw Error(r.status);return r.json()}
$('search').oninput=countryList;$('regionSearch').oninput=renderRegionList;document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{continent=b.dataset.cont;document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('selected',x===b));countryList()});$('home').onclick=()=>world&&goHome();$('back').onclick=goHome;$('learn').onclick=learn;$('quiz').onclick=()=>{ $('skip').textContent='不知道，顯示答案 →';$('skip').onclick=()=>answer(null);startQuiz()};$('skip').onclick=()=>answer(null);$('restart').onclick=()=>startQuiz();$('zoomIn').onclick=()=>svg.transition().duration(200).call(zoom.scaleBy,1.5);$('zoomOut').onclick=()=>svg.transition().duration(200).call(zoom.scaleBy,1/1.5);$('resetZoom').onclick=()=>svg.transition().duration(250).call(zoom.transform,d3.zoomIdentity);$('about').onclick=$('sourceLink').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(world)renderMap()},150)});
Promise.all([getJSON('data/catalog.json'),getJSON('data/world.json')]).then(([cs,w])=>{catalog=cs;world=w;$('countryCount').textContent=cs.length;countryList();renderMap()}).catch(()=>{$('countryList').innerHTML='<p>地圖載入失敗，請重新整理頁面。</p>'});

function clearRound(){queue=[];qIndex=0;correct=0;wrong=[];skipped=[];completed=new Set();revealed=null;wrongSelected=null;finished=false;$('results').hidden=true;$('nextQuestion').hidden=true}
function hasProgress(){return mode==='quiz'&&!finished&&completed.size>0}
function confirmLeave(){return !hasProgress()||window.confirm('離開將清除本輪進度，確定繼續？')}
function advance(){if(!locked||finished)return;clearTimeout(timer);timer=null;qIndex++;nextQuestion()}
function refreshRegionState(){if(!regions)return;for(const sel of [shapes.selectAll('path'),pins.selectAll('circle')])sel.classed('completed',d=>mode==='quiz'&&completed.has(d.properties.id)).classed('correct',d=>mode==='quiz'&&d===revealed).classed('wrong',d=>mode==='quiz'&&d===wrongSelected).classed('active',false);drawLabels(mode==='learn'?regions.features:regions.features.filter(f=>completed.has(f.properties.id)))}
function ensureVisible(f){const t=d3.zoomTransform(svg.node()),a=t.apply(anchor(f));if(a[0]<70||a[0]>W-70||a[1]<90||a[1]>H-75){const p=anchor(f);svg.transition().duration(250).call(zoom.transform,d3.zoomIdentity.translate(W/2,H/2).scale(t.k).translate(-p[0],-p[1]))}}
function layoutLabels(){if(!path||!projection)return;const t=d3.zoomTransform(svg.node()),placed=[];labels.selectAll('g').each(function(f){const p=t.apply(anchor(f)),b=this._labelBox;if(!b)return;d3.select(this).attr('transform',`translate(${anchor(f)}) scale(${1/t.k})`);const rect={x:p[0]+b.x-4,y:p[1]+b.y-3,w:b.width+8,h:b.height+6};const outside=rect.x<8||rect.y<58||rect.x+rect.w>W-8||rect.y+rect.h>H-38;const overlaps=placed.some(r=>rect.x<r.x+r.w&&rect.x+rect.w>r.x&&rect.y<r.y+r.h&&rect.y+rect.h>r.y);const visible=!outside&&!overlaps;this.style.display=visible?'':'none';if(visible)placed.push(rect)})}
function validateRegions(fc){if(fc.type!=='FeatureCollection'||!Array.isArray(fc.features))throw Error('Invalid data');const ids=new Set();fc.features=fc.features.filter(f=>f.geometry&&['Polygon','MultiPolygon'].includes(f.geometry.type)&&[f.properties.local,f.properties.en,f.properties.zh].some(n=>n&&!n.includes('待補')));for(const f of fc.features){if(ids.has(f.properties.id)||f.properties.boundary_version!==country.boundary_version)throw Error('Data version mismatch');ids.add(f.properties.id)}}
$('nextQuestion').onclick=advance;$('resultLearn').onclick=learn;$('resultHome').onclick=goHome;
window.addEventListener('beforeunload',e=>{if(hasProgress()){e.preventDefault();e.returnValue=''}});
document.fonts?.ready.then(()=>{if(regions)refreshRegionState()});
